+            break;
+        case 'b':
+            /* Random bold characters */
+            break;
+        case 'B':
+            /* All bold characters */
+            break;
+        case 'n':
+            /* Turn off bold characters */
+            break;
+        case '0':
+        case '1':
+        case '2':
+        case '3':
+        case '4':
+        case '5':
+        case '6':
+        case '7':
+        case '8':
+        case '9':
+            /* Adjust update speed */
+            break;
+        case '!':
+            /* Change color to red */
+            break;
+        case '@':
+            /* Change color to green */
+            break;
+        case '#':
+            /* Change color to yellow */
+            break;
+        case '$':
+            /* Change color to blue */
+            break;
+        case '%':
+            /* Change color to magenta */
+            break;
+        case '^':
+            /* Change color to cyan */
+            break;
+        case '&':
+            /* Change color to white */
+            break;
+        case ')':
+            /* Change color to black */
+            break;
+        case 'q':
