    fprintf(stderr, "Error: %s\n", msg);
    options_print_version();
    exit(1);
}

int validate_color(const char *color) {
    if (color == NULL) return 1;

    const char *valid_colors[] = {"green", "red", "blue", "white", "yellow", "cyan", "magenta", "black", NULL};
    int i;

    for (i = 0; valid_colors[i] != NULL; i++) {
        if (strcmp(color, valid_colors[i]) == 0) {
            return 1;
        }
    }

    return 0;
}

int validate_delay(int delay) {
    if (delay < 0 || delay > 10) {
        return 0;
    }
    return 1;
}
